#include <bits/stdc++.h>
using namespace std;
int main(){
    int n;
    int caseNum = 0;
    while (cin >> n && n != 0) {
        cin.ignore();
        vector<string> stdLines(n);
        long long y = 0;
        for (int i = 0; i < n; i++) { getline(cin, stdLines[i]); y += (long long)stdLines[i].size(); }
        int m; cin >> m; cin.ignore();
        vector<string> teamLines(m);
        for (int i = 0; i < m; i++) getline(cin, teamLines[i]);
        string stdText, teamText;
        for (int i = 0; i < n; i++) { if (i) stdText += "\n"; stdText += stdLines[i]; }
        for (int i = 0; i < m; i++) { if (i) teamText += "\n"; teamText += teamLines[i]; }
        caseNum++;
        if (stdText == teamText) {
            cout << "Run #" << caseNum << ": Accepted " << y << "\n";
        } else {
            auto stripWs = [](const string &s){ string r; for (char c : s) if (c != ' ' && c != '\n') r += c; return r; };
            if (stripWs(stdText) == stripWs(teamText)) cout << "Run #" << caseNum << ": Presentation Error " << y << "\n";
            else cout << "Run #" << caseNum << ": Wrong Answer " << y << "\n";
        }
    }
}

